#!/usr/bin/env python3
import json
import glob
import os
import sys
import time
from collections import defaultdict

BASE = os.path.dirname(os.path.abspath(__file__ + "/.."))
TASKS_DIR = sys.argv[1] if len(sys.argv) > 1 else os.path.join(BASE, "data", "tasks")

def agent_from_event(path):
    try:
        with open(path) as f:
            return json.load(f)
    except Exception:
        return None

def main():
    if not os.path.isdir(TASKS_DIR):
        print(json.dumps({"error": "no_tasks_dir"}))
        return
    stats = defaultdict(lambda: {
        "total": 0, "success": 0, "error": 0, "running": 0
    })
    total_runtime = 0
    count_runtime = 0
    now = time.time()
    stale_events = []
    for path in sorted(glob.glob(os.path.join(TASKS_DIR, "*.json"))):
        state = agent_from_event(path)
        if state is None:
            continue
        agent = state.get("agent", "desconhecido")
        st = stats[agent]
        st["total"] += 1
        if state.get("state") == "success":
            st["success"] += 1
        elif state.get("state") == "error":
            st["error"] += 1
        elif state.get("state") == "running":
            st["running"] += 1
            started = state.get("started_at")
            if started and (now - started) > 1800:
                stale_events.append({
                    "agent": agent, "task": state.get("id"),
                    "minutes_running": int((now - started) / 60),
                })
        if isinstance(state.get("runtime_ms"), (int, float)):
            total_runtime += state["runtime_ms"]
            count_runtime += 1

    out = {"timestamp": int(now * 1000), "agents": []}
    for agent, st in stats.items():
        entry = dict(st)
        entry["agent"] = agent
        entry["success_rate"] = round(100 * st["success"] / st["total"], 2) if st["total"] else 0.0
        out["agents"].append(entry)
    out["avg_runtime_ms"] = round(total_runtime / count_runtime, 1) if count_runtime else 0.0
    out["stale"] = stale_events
    print(json.dumps(out))

if __name__ == "__main__":
    main()

